class Solution:
    def maxUniqueSplit(self, s: str) -> int:
        self.best = 0
        def backtrack(start, used):
            if start == len(s):
                self.best = max(self.best, len(used))
                return
            if len(used) + (len(s) - start) <= self.best:
                return
            for end in range(start + 1, len(s) + 1):
                sub = s[start:end]
                if sub not in used:
                    used.add(sub)
                    backtrack(end, used)
                    used.remove(sub)
        backtrack(0, set())
        return self.best

